<?php
/**
 * Where the plugin's settings live. Three options:
 *  - aworacle_settings      (autoloaded; no secrets): embed mode, engine URLs, key id, locale map, default locale, page map,
 *                           mailer (fluentcrm | none: the daily letter), turnstile_site_key (public half of the signup form's
 *                           Cloudflare Turnstile keys)
 *  - aworacle_site_keypair  (not autoloaded; secret): base64 Ed25519 keypair, generated by the admin —
 *                           or the constant AWORACLE_SITE_KEYPAIR in wp-config.php, which wins (keeps the
 *                           private key out of the database and its backups)
 *  - aworacle_member_salt   (not autoloaded; secret): salt for member pseudonyms HMAC(salt, user id),
 *                           created the first time it is needed (activation hooks do not run on every install path)
 * Plus one constant that is never an option: AWORACLE_DATA_KEY (wp-config.php, base64 of 32 bytes) encrypts
 * members' saved birth data (Crypto\Vault). Without it saving is off; nothing falls back to plaintext.
 * AWORACLE_RESEND_WEBHOOK_SECRET (wp-config.php) verifies Resend's bounce/complaint webhook.
 * The Turnstile secret: constant AWORACLE_TURNSTILE_SECRET (wins) or option aworacle_turnstile_secret (not autoloaded).
 *
 * @package AwareWave\Oracle\Settings
 */

namespace AwareWave\Oracle\Settings;

use AwareWave\Oracle\Crypto\Vault;

final class Options {

	const OPTION       = 'aworacle_settings';
	const KEY_OPTION   = 'aworacle_site_keypair';
	const KEY_CONSTANT = 'AWORACLE_SITE_KEYPAIR';
	const SALT_OPTION  = 'aworacle_member_salt';
	const DATA_KEY_CONSTANT = 'AWORACLE_DATA_KEY';
	/** Resend webhook signing secret ("whsec_…"), wp-config.php only. */
	const WEBHOOK_SECRET_CONSTANT = 'AWORACLE_RESEND_WEBHOOK_SECRET';
	const TURNSTILE_SECRET_OPTION   = 'aworacle_turnstile_secret';
	const TURNSTILE_SECRET_CONSTANT = 'AWORACLE_TURNSTILE_SECRET';

	/** @return array{embed:string,browser_engine_url:string,server_engine_url:string,key_id:string,default_locale:string,locale_map:array<string,string>,page_map:array<string,int>,mailer:string,turnstile_site_key:string} */
	public static function defaults(): array {
		return array(
			'embed'              => Normalize::EMBED_SAME_ORIGIN,
			'browser_engine_url' => '',
			'server_engine_url'  => '',
			'key_id'             => '',
			'default_locale'     => 'en',
			'locale_map'         => array(),
			'page_map'           => array(),
			'mailer'             => Normalize::MAILER_NONE,
			'turnstile_site_key' => '',
		);
	}

	/** @return array{embed:string,browser_engine_url:string,server_engine_url:string,key_id:string,default_locale:string,locale_map:array<string,string>,page_map:array<string,int>,mailer:string,turnstile_site_key:string} */
	public static function get(): array {
		$stored = get_option( self::OPTION, array() );
		$out    = array_merge( self::defaults(), is_array( $stored ) ? $stored : array() );
		// Cross-origin is not supported yet: a value stored before that decision is read as same-origin.
		$out['embed'] = Normalize::EMBED_SAME_ORIGIN;
		return $out;
	}

	/**
	 * Where this WordPress server calls the engine. Set explicitly, or: cross-origin → the browser URL;
	 * same-origin → this site's own origin (the engine answers under the same domain).
	 */
	public static function serverEngineUrl(): string {
		$s = self::get();
		if ( $s['server_engine_url'] !== '' ) {
			return $s['server_engine_url'];
		}
		if ( $s['embed'] === Normalize::EMBED_CROSS_ORIGIN ) {
			return $s['browser_engine_url'];
		}
		$home = wp_parse_url( home_url( '/' ) );
		if ( ! is_array( $home ) || empty( $home['scheme'] ) || empty( $home['host'] ) ) {
			return '';
		}
		return Normalize::engineUrl( $home['scheme'] . '://' . $home['host'] . ( isset( $home['port'] ) ? ':' . $home['port'] : '' ), true );
	}

	public static function keypairFromConstant(): bool {
		return defined( self::KEY_CONSTANT ) && is_string( constant( self::KEY_CONSTANT ) ) && constant( self::KEY_CONSTANT ) !== '';
	}

	public static function keypair(): string {
		if ( self::keypairFromConstant() ) {
			return (string) constant( self::KEY_CONSTANT );
		}
		return (string) get_option( self::KEY_OPTION, '' );
	}

	/** 'ok', 'missing' (constant not defined) or 'invalid' (not base64 of 32 bytes). */
	public static function dataKeyStatus(): string {
		if ( ! defined( self::DATA_KEY_CONSTANT ) ) {
			return 'missing';
		}
		$value = constant( self::DATA_KEY_CONSTANT );
		return is_string( $value ) && Vault::keyFromBase64( $value ) !== '' ? 'ok' : 'invalid';
	}

	/** Raw 32-byte member-data key, or '' when saving is off (see dataKeyStatus()). */
	public static function dataKey(): string {
		return self::dataKeyStatus() === 'ok' ? Vault::keyFromBase64( (string) constant( self::DATA_KEY_CONSTANT ) ) : '';
	}

	/** The Resend webhook signing secret, or '' when not configured. */
	public static function webhookSecret(): string {
		$v = defined( self::WEBHOOK_SECRET_CONSTANT ) ? constant( self::WEBHOOK_SECRET_CONSTANT ) : '';
		return is_string( $v ) ? trim( $v ) : '';
	}

	public static function turnstileSecretFromConstant(): bool {
		return defined( self::TURNSTILE_SECRET_CONSTANT ) && is_string( constant( self::TURNSTILE_SECRET_CONSTANT ) ) && trim( constant( self::TURNSTILE_SECRET_CONSTANT ) ) !== '';
	}

	/** The Turnstile secret, or '' when not configured. */
	public static function turnstileSecret(): string {
		if ( self::turnstileSecretFromConstant() ) {
			return trim( (string) constant( self::TURNSTILE_SECRET_CONSTANT ) );
		}
		return trim( (string) get_option( self::TURNSTILE_SECRET_OPTION, '' ) );
	}

	public static function activate(): void {
		self::salt();
	}

	public static function newSalt(): string {
		return base64_encode( random_bytes( 32 ) );
	}

	/**
	 * The pseudonym salt, created on first use. Not add_option: it ends in INSERT … ON DUPLICATE KEY UPDATE,
	 * so two first requests would each write their own salt and the loser's pseudonyms would change.
	 * INSERT IGNORE keeps whichever row landed first; caches are dropped and the row is read back.
	 */
	public static function salt(): string {
		$salt = (string) get_option( self::SALT_OPTION, '' );
		if ( $salt !== '' ) {
			return $salt;
		}
		global $wpdb;
		$wpdb->query(
			$wpdb->prepare(
				"INSERT IGNORE INTO {$wpdb->options} (option_name, option_value, autoload) VALUES (%s, %s, %s)",
				self::SALT_OPTION,
				self::newSalt(),
				'no' // not autoloaded; 'no' is understood by 6.5 and later
			)
		);
		wp_cache_delete( self::SALT_OPTION, 'options' );
		wp_cache_delete( 'notoptions', 'options' );
		return (string) $wpdb->get_var( $wpdb->prepare( "SELECT option_value FROM {$wpdb->options} WHERE option_name = %s", self::SALT_OPTION ) );
	}

	/** The pseudonym the engine sees for a member: never the user id or e-mail itself. */
	public static function memberPseudonym( int $userId ): string {
		if ( $userId <= 0 ) {
			return '';
		}
		$salt = self::salt();
		return $salt === '' ? '' : hash_hmac( 'sha256', (string) $userId, $salt );
	}
}
